AX = {"xp": (0, +1), "xn": (0, -1), "yp": (1, +1), "yn": (1, -1), "zp": (2, +1), "zn": (2, -1)}
def side(c):                                   # which face-direction a feature points to
    t = c.to_tuple()
    return max(AX, key=lambda k: AX[k][1] * t[AX[k][0]])

patches = {}
for f in water.faces():
    c = f.bounding_box().center()
